import React, { useState, useEffect } from 'react';
import api from '../api';

const OrganizerStudio = ({ events, onEventCreated, showToast }) => {
    const [stats, setStats] = useState({ totalRevenue: 0, totalSold: 0, totalCapacity: 192, totalTickets: 0, usedTickets: 0 });
    const [title, setTitle] = useState('');
    const [category, setCategory] = useState('Concerts');
    const [eventDate, setEventDate] = useState('Dec 18, 2026 • 20:00');
    const [venue, setVenue] = useState('');
    const [vipPrice, setVipPrice] = useState(320);
    const [gaPrice, setGaPrice] = useState(140);

    const fetchStats = async () => {
        try {
            const res = await api.get('/organizer/stats');
            setStats(res.data);
        } catch (err) {
            console.error(err);
        }
    };

    useEffect(() => {
        fetchStats();
    }, [events]);

    const handlePublish = async (e) => {
        e.preventDefault();
        try {
            await api.post('/organizer/events', {
                title,
                category,
                eventDate,
                venue,
                vipPrice: Number(vipPrice),
                gaPrice: Number(gaPrice)
            });
            setTitle('');
            setVenue('');
            showToast(`"${title}" published! Now live in the Client Event Catalog.`, 'success');
            onEventCreated();
            fetchStats();
        } catch (err) {
            showToast('Failed to publish event (Organizer or Admin role required).', 'error');
        }
    };

    const checkinRate = stats.totalTickets > 0 ? Math.round((stats.usedTickets / stats.totalTickets) * 100) : 0;

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="bg-slate-900 border border-slate-800 rounded-2xl p-5">
                    <p className="text-xs font-semibold uppercase tracking-wider text-slate-400">Gross Ticket Revenue</p>
                    <p className="text-2xl font-extrabold font-mono text-emerald-400 mt-1">{Number(stats.totalRevenue).toLocaleString()} RON</p>
                    <p className="text-xs text-slate-500 mt-1">Live MySQL ledger</p>
                </div>
                <div className="bg-slate-900 border border-slate-800 rounded-2xl p-5">
                    <p className="text-xs font-semibold uppercase tracking-wider text-slate-400">Total Seats Sold</p>
                    <p className="text-2xl font-extrabold font-mono text-cyan-400 mt-1">{stats.totalSold} / {stats.totalCapacity}</p>
                    <p className="text-xs text-slate-500 mt-1">Across all active events</p>
                </div>
                <div className="bg-slate-900 border border-slate-800 rounded-2xl p-5">
                    <p className="text-xs font-semibold uppercase tracking-wider text-slate-400">IoT Gate Check-In Rate</p>
                    <p className="text-2xl font-extrabold font-mono text-indigo-400 mt-1">{checkinRate}%</p>
                    <p className="text-xs text-slate-500 mt-1">{stats.usedTickets} of {stats.totalTickets} tickets scanned</p>
                </div>
                <div className="bg-slate-900 border border-slate-800 rounded-2xl p-5">
                    <p className="text-xs font-semibold uppercase tracking-wider text-slate-400">Staff Cost Saved (IoT)</p>
                    <p className="text-2xl font-extrabold font-mono text-amber-400 mt-1">4,200 RON</p>
                    <p className="text-xs text-slate-500 mt-1">Autonomous lanes active</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                <div className="lg:col-span-5 bg-slate-900 border border-slate-800 rounded-2xl p-5 sm:p-6">
                    <h3 className="text-lg font-bold text-white mb-1">Create &amp; Publish New Event</h3>
                    <p className="text-xs text-slate-400 mb-4">Automatically generates a 48-seat interactive venue matrix in MySQL.</p>

                    <form onSubmit={handlePublish} className="space-y-3.5">
                        <div>
                            <label className="block text-xs font-semibold text-slate-300 mb-1">Event Title</label>
                            <input required type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="e.g., Subcarpați Symphonic Live" className="w-full px-3.5 py-2 rounded-xl bg-slate-950 border border-slate-700 text-sm text-white focus:outline-none focus:border-cyan-500" />
                        </div>
                        <div className="grid grid-cols-2 gap-3">
                            <div>
                                <label className="block text-xs font-semibold text-slate-300 mb-1">Category</label>
                                <select value={category} onChange={(e) => setCategory(e.target.value)} className="w-full px-3 py-2 rounded-xl bg-slate-950 border border-slate-700 text-sm text-white focus:outline-none focus:border-cyan-500">
                                    <option value="Concerts">Concerts</option>
                                    <option value="Festivals">Festivals</option>
                                    <option value="Theater">Theater</option>
                                    <option value="Comedy">Comedy</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-semibold text-slate-300 mb-1">Event Date</label>
                                <input required type="text" value={eventDate} onChange={(e) => setEventDate(e.target.value)} className="w-full px-3 py-2 rounded-xl bg-slate-950 border border-slate-700 text-sm text-white focus:outline-none focus:border-cyan-500" />
                            </div>
                        </div>
                        <div>
                            <label className="block text-xs font-semibold text-slate-300 mb-1">Venue &amp; City</label>
                            <input required type="text" value={venue} onChange={(e) => setVenue(e.target.value)} placeholder="e.g., BTarena, Cluj-Napoca" className="w-full px-3.5 py-2 rounded-xl bg-slate-950 border border-slate-700 text-sm text-white focus:outline-none focus:border-cyan-500" />
                        </div>
                        <div className="grid grid-cols-2 gap-3">
                            <div>
                                <label className="block text-xs font-semibold text-slate-300 mb-1">VIP Price (RON)</label>
                                <input required type="number" min="50" value={vipPrice} onChange={(e) => setVipPrice(e.target.value)} className="w-full px-3.5 py-2 rounded-xl bg-slate-950 border border-slate-700 text-sm font-mono text-white focus:outline-none focus:border-cyan-500" />
                            </div>
                            <div>
                                <label className="block text-xs font-semibold text-slate-300 mb-1">General Access (RON)</label>
                                <input required type="number" min="20" value={gaPrice} onChange={(e) => setGaPrice(e.target.value)} className="w-full px-3.5 py-2 rounded-xl bg-slate-950 border border-slate-700 text-sm font-mono text-white focus:outline-none focus:border-cyan-500" />
                            </div>
                        </div>
                        <button type="submit" className="w-full py-3 rounded-xl bg-gradient-to-r from-cyan-500 to-emerald-500 hover:from-cyan-400 hover:to-emerald-400 text-slate-950 font-bold text-sm shadow-lg shadow-cyan-500/20 transition">
                            + Publish Event to Catalog
                        </button>
                    </form>
                </div>

                <div className="lg:col-span-7 bg-slate-900 border border-slate-800 rounded-2xl p-5 sm:p-6 space-y-4">
                    <div className="flex items-center justify-between">
                        <h3 className="text-lg font-bold text-white">Live Event Inventory &amp; Gate Attendance</h3>
                        <span className="text-xs font-mono text-emerald-400">● Real-time MySQL Sync</span>
                    </div>
                    <div className="space-y-4">
                        {events.map(ev => {
                            const pct = Math.round((ev.soldCount / ev.totalCapacity) * 100);
                            return (
                                <div key={ev.id} className="bg-slate-950 border border-slate-800 rounded-xl p-4 space-y-2.5">
                                    <div className="flex flex-wrap items-center justify-between gap-2">
                                        <div>
                                            <h4 className="font-bold text-white text-sm">{ev.title}</h4>
                                            <p className="text-xs text-slate-400">{ev.venue} • {ev.date}</p>
                                        </div>
                                        <span className="font-mono text-xs font-bold text-cyan-300">{ev.soldCount} / {ev.totalCapacity} Seats Sold ({pct}%)</span>
                                    </div>
                                    <div className="w-full h-2.5 bg-slate-800 rounded-full overflow-hidden">
                                        <div className="h-full bg-gradient-to-r from-cyan-500 to-emerald-400 rounded-full transition-all duration-500" style={{ width: `${pct}%` }}></div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default OrganizerStudio;
